begin;
set local role postgres;
set local search_path = public, extensions;create extension if not exists pgtap with schema extensions;select plan(11);select has_table('public','on_demand_workflow_runs','Production workflow runs persist');select has_column('public','on_demand_workflow_runs','idempotency_key','Requests are idempotent');select has_column('public','on_demand_workflow_runs','target_decision_id','Target decision is linked');select has_column('public','on_demand_workflow_runs','generation_contract_id','Contract is linked');select has_column('public','on_demand_workflow_runs','reuse_decision_id','Reuse decision is linked');select has_column('public','on_demand_workflow_runs','generation_run_id','Generation is linked');select has_column('public','on_demand_workflow_runs','candidate_set_decision_id','QA decision is linked');select has_column('public','on_demand_workflow_runs','selected_serving_version_id','Serving result is linked');select has_table('public','on_demand_workflow_events','Stage ledger persists');select col_is_unique('public','on_demand_workflow_runs',array['student_id','idempotency_key'],'Student request runs once');select has_function('public','claim_on_demand_workflow_run',array[]::text[],'Workers claim queued runs without races');select * from finish();rollback;
